// Shared contracts for every Roster module. Shapes follow docs/DESIGN.md §"Data model".
// Change minimally, and say so in your PR.

/** Evidence level printed next to every claim: A observational, B controlled replay, C forward. */
export type EvidenceLevel = "A" | "B" | "C";
export const EVIDENCE_LEVELS: readonly EvidenceLevel[] = ["A", "B", "C"] as const;

/** Failure taxonomy (DESIGN.md §"Grade"). */
export enum FailureCode {
  /** edited tests */
  F1 = "F1",
  /** never ran tests */
  F2 = "F2",
  /** suite regression */
  F3 = "F3",
  /** stopped early */
  F4 = "F4",
  /** loop, timeout or turn cap */
  F5 = "F5",
  /** environment or setup error; the task is excluded and resampled */
  F6 = "F6",
  /** off-scope edits */
  F7 = "F7",
}

/** Where a session row came from. */
export type SessionSource = "branch" | "git-refs";

/** One agent session, aggregated over all checkpoints it appears in. Table `sessions`. */
export interface Session {
  id: string;
  repo: string;
  checkpoint_id: string;
  harness: string;
  /** Resolved model, or "unknown" when neither metadata nor transcript records it. */
  model: string;
  /** sha256 of the normalised rules file; null when unknown, never a guess. */
  rules_hash: string | null;
  setup_id: string | null;
  tokens_in: number;
  tokens_out: number;
  cache_read: number;
  cache_write: number;
  /** null when the model's price is unknown. */
  cost_usd: number | null;
  n_user_prompts: number;
  first_prompt: string;
  /** null when no commit carries this session's checkpoint trailer. */
  commit_sha: string | null;
  started_at: string;
  ended_at: string;
  files: string[];
  entire_url: string | null;
  source: SessionSource;
}

export type OutcomeStatus = "mature" | "too_young";
export type Tercile = 1 | 2 | 3;

/** Score of one session. Metrics are null when status is too_young. Table `outcomes`. */
export interface Outcome {
  session_id: string;
  status: OutcomeStatus;
  survival: number | null;
  reverted: boolean | null;
  rework_human: number | null;
  rework_agent: number | null;
  unattended: boolean | null;
  tests_at_commit: boolean | null;
  difficulty: number | null;
  tercile: Tercile | null;
}

/** Setup = harness + model + rules_hash. Table `setups`. */
export interface Setup {
  id: string;
  harness: string;
  model: string;
  rules_hash: string | null;
  rules_path: string | null;
  label: string;
}

/** Coordinator plan. Table `plans`; `json` holds the serialised PlanBody. */
export interface Plan {
  id: string;
  review_id: string;
  json: string;
  rationale: string;
  created_at: string;
}

/** Body of plan.json (DESIGN.md §"Plan (coordinator)"). */
export interface PlanBody {
  suspect: string | null;
  /** Session ids, ≤ 12, stratified by tercile. */
  tasks: string[];
  /** Setup ids, ≤ 3 per iteration. */
  candidates: string[];
  budget_usd: number;
  stop_rules: string[];
  rationale: string;
}

export type ReplayVerdict =
  | "agent_error"
  | "no_changes"
  | "hidden_tests_failed"
  | "suite_failed"
  | "guardrail_flagged"
  | "pass";

/** One replay attempt of a task under a setup. Table `replays`. */
export interface Replay {
  id: string;
  plan_id: string;
  task_session_id: string;
  setup_id: string;
  attempt: number;
  isolation_proof: string;
  turns: number | null;
  duration_ms: number | null;
  cost_usd: number | null;
  hidden_pass: boolean | null;
  suite_pass: boolean | null;
  scope_ok: boolean | null;
  judge_equiv: boolean | null;
  failure_codes: FailureCode[];
  verdict: ReplayVerdict;
  transcript_ref: string | null;
  trace_url: string | null;
}

export type GateVerdict = "promote" | "reject";

/** Table `gate_decisions`. */
export interface GateDecision {
  id: string;
  plan_id: string;
  candidate: string;
  verdict: GateVerdict;
  reasons: string[];
  trace_url: string | null;
}

/** One pre-registered forward task run through both setups. Table `forward_pairs`. */
export interface ForwardPair {
  task_id: string;
  setup_old: string;
  setup_new: string;
  pass_old: boolean;
  pass_new: boolean;
  cost_old: number | null;
  cost_new: number | null;
  /** Which setup's change was merged, if any. */
  merged: "old" | "new" | null;
  /** Blind label assignment, e.g. { X: "old", Y: "new" }. */
  blind_labels: Record<string, "old" | "new">;
  seed: number;
}

export type ReviewLabel = "suspect" | "no_suspect" | "insufficient_data";

/** Difficulty-matched scorecard result (DESIGN.md §"Difficulty and review"). */
export interface Review {
  id: string;
  repo: string;
  created_at: string;
  label: ReviewLabel;
  /** Setup id when label is "suspect". */
  suspect: string | null;
  /** Mantel–Haenszel odds ratio, setup X vs the rest, stratified by tercile. */
  odds_ratio: number | null;
  ci95: [number, number] | null;
  p_value: number | null;
  evidence_level: EvidenceLevel;
}
21: → Replay   each task at its parent commit in an isolated sandbox; incumbent + candidates
22- → Grade    hidden acceptance tests · suite at parent · scope guard · blind diff-judge · reruns
23- → Gate     promote only if nothing regresses                                         evidence level B (controlled replay)
24:     └ reject → Candidates: a new rules file from the failure taxonomy → Replay
25- → Act      pull request: setups/<id>.json + rules file + evidence
26- → Forward  pre-registered new tasks, paired old vs new, blind grading                evidence level C (forward)
27- → Book     cfo.ai: AI Workforce department + hire-vs-scale scenario, read back to verify
28-```
29-
30-The rule: a setup is never called "worse" on level A alone. Every page prints the evidence level next to every claim.
31-
32-## Setups
33-
34-**Setup** = `harness` + `model` + `rules_hash` (+ `plugins_hash` when recorded).
35-
36-| Part | Where it comes from |
37-|---|---|
38-| `harness` | Entire metadata |
39-| `model` | The **resolved** model the run reports (e.g. `modelUsage`), never the requested flag |
40-| `rules_hash` | sha256 of the rules file in effect at the session's parent commit, normalised (LF line endings, trimmed): `CLAUDE.md` for Claude Code, `AGENTS.md` for Codex, `.cursor/rules/*` / `.cursorrules` for Cursor. It also covers any appended system prompt the session records. If unknown, `null`; never a guess |
41-
42-### The four setups building this repo
43-These live in `setups/`:
44-
45-| Id | Harness | Model | Rules |
46-|---|---|---|---|
47-| A | Claude Code | Opus 5.5 | `setups/rules/default.md` |
48-| B | Claude Code | Sonnet 5.5 | default |
49-| C | Codex CLI (or Claude Code + Haiku 5.5, if Codex is unavailable; logged in `experiments/PREREGISTRATION.md`) | | default (as `AGENTS.md`) |
--
178:### Replay at the parent commit
179-- **Sandbox:**
180-  1. `git archive <parent> | tar -x` into a fresh directory.
181-  2. `git init`, then one base commit with a fixed author and date.
182-  3. Isolation proof: zero objects from `git rev-list --objects --all ^<parent>` exist in the sandbox, there are no remotes, a single ref, and no reflog beyond the base.
183-  - Clone + reset is forbidden (it's a denylist and leaks).
184-- **Rules swap:** write the setup's rules file into the sandbox and commit it as `setup:`, so the agent's diff excludes it.
185-- **Harness adapters** (`src/harness/*`, one contract):
186-  - **Claude Code:**
187-    ```
188-    claude -p "<task>" --model <m> --output-format json --max-turns 30
189-      --permission-mode acceptEdits --permission-prompts none --allowedTools "<allowlist>"
190-      --setting-sources project --strict-mcp-config --disable-slash-commands --max-budget-usd <cap>
191-    ```
192-    The child env is scrubbed of host-session variables. A setup file may carry provider env (`env`, with `${VAR}` filled from `.env`). DeepSeek candidates set `ANTHROPIC_BASE_URL=https://api.deepseek.com/anthropic`, `ANTHROPIC_AUTH_TOKEN` and the `ANTHROPIC_DEFAULT_*_MODEL` names. That endpoint ignores `cache_control`.
193-    JSON fields: `session_id, num_turns, duration_ms, total_cost_usd, usage, modelUsage, is_error, stop_reason`.
194-  - **Codex:**
195-    ```
196-    codex exec --json --model <m> --sandbox workspace-write -c approval_policy=never -C <ws> "<task>"
197-    ```
198-    Rules go in `AGENTS.md`. Tokens come from `turn.completed.usage`; it reports no USD (price it via `src/price`) and has no turn cap (use a wall-clock timeout).
199-- **Save:** `agent.patch` (`git diff --binary`) and the raw JSON or stream-json transcript.
200-- **Where replays run:** replays of public repos run only in isolated microVMs. Replays of this repo may run locally.
201-
202-### Grade
203-1. **Grade in a separate copy:** base + `agent.patch` + hidden tests. Never grade in the agent's workspace.
