import { existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { gitEnv, runGit } from "../sandbox/index.ts";
import type { Sandbox } from "../sandbox/index.ts";
import { offScopeViolations, testEditViolations } from "./scope.ts";
import type { Violation } from "./scope.ts";
import type { HiddenTest } from "./hidden.ts";

export { hiddenTests, isTestFile } from "./hidden.ts";
export type { HiddenTest } from "./hidden.ts";
export type { Violation } from "./scope.ts";

export interface PerTest {
  file: string;
  name: string;
  pass: boolean;
}

export interface GradeResult {
  hiddenPass: boolean;
  suitePass: boolean;
  scopeOk: boolean;
  violations: Violation[];
  perTest: PerTest[];
}

export interface GradeInput {
  /** The agent's workspace. Read only: grading happens in a fresh copy. */
  sandbox: Sandbox;
  hidden: HiddenTest[];
  /** Override for the auto-detected test command. */
  testCmd?: string;
  /** Repo-relative paths of test files that existed at base. */
  preexistingTests: string[];
  /** Directories the original change touched; when omitted the off-scope check is skipped. */
  touchedDirs?: string[];
  timeoutMs?: number;
}

import { afterAll, beforeAll, describe, expect, test } from "bun:test";
import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { grade, detectTestCmd, hiddenTests } from "../src/grade/index.ts";
import { createSandbox, destroySandbox, runGit } from "../src/sandbox/index.ts";
import { FailureCode } from "../src/types.ts";

const ADD_TEST = `import { expect, test } from "bun:test";
import { add } from "../src/add.ts";
test("add", () => { expect(add(1, 2)).toBe(3); });
`;
const MUL_TEST = `import { expect, test } from "bun:test";
import { mul } from "../src/mul.ts";
test("mul", () => { expect(mul(2, 3)).toBe(6); });
`;
const MUL_SRC = "export const mul = (a: number, b: number) => a * b;\n";

let tmp: string;
let repo: string;
let baseSha: string;
let originalSha: string;
let roots = 0;

function put(root: string, rel: string, content: string) {
  mkdirSync(dirname(join(root, rel)), { recursive: true });
  writeFileSync(join(root, rel), content);
}
function commit(msg: string) {
  runGit(repo, ["add", "-A"]);
