  const out: GateResults = [];
  for (const [task, attempts] of Object.entries(spec)) {
    [...attempts].forEach((a, i) => {
      out.push({
        task_session_id: task,
        attempt: i + 1,
        hidden_pass: a === "P" || a === "S",
        scope_ok: a !== "S",
        cost_usd: cost,
